-- The backtest's statistics over time (research 2026-10-13, the same copy trips as backtest_stats,
-- as of the backtest's end): daily Sharpe and Sortino of the copy's return (a year's), its
-- return a month over its max drawdown (Calmar), PnL of the trips closed in its last 30 days,
-- the share of its weeks with a closed trip that were in profit, and how many such weeks.
ALTER TABLE backtest_stats ADD COLUMN IF NOT EXISTS sharpe_d float8, ADD COLUMN IF NOT EXISTS sortino_d float8,
    ADD COLUMN IF NOT EXISTS calmar float8, ADD COLUMN IF NOT EXISTS pnl_30d float8,
    ADD COLUMN IF NOT EXISTS weeks_pos float8, ADD COLUMN IF NOT EXISTS weeks integer;
UPDATE backtest_stats b SET sharpe_d = v.sharpe_d, sortino_d = v.sortino_d, calmar = v.calmar, pnl_30d = v.pnl_30d,
    weeks_pos = v.weeks_pos, weeks = v.weeks
